style.css:
@-moz-document domain("youtube.com") {
/* Fondo principal de la página (Amarillo Pastel) */
    html, body, ytd-app, #page-manager, 
    ytd-browse, ytd-watch-flexy, #contentContainer,
    ytd-masthead, #background.ytd-masthead {
        background-color: #FFF9E3 !important;
    }

    /* Textos principales, títulos y nombres de canales (Marrón Pastel) */
    h1, h2, h3, span, a, #video-title, 
    .title.ytd-video-primary-info-renderer,
    #channel-name .yt-simple-endpoint,
    #content-text.ytd-comment-renderer {
        color: #6D4C41 !important;
    }

    /* Barra superior de navegación (Amarillo Pastel más intenso) */
    #masthead-container {
        background-color: #FFF5CC !important;
        border-bottom: 2px solid #6D4C41 !important;
    }

    /* Barra de búsqueda (Fondo claro con borde marrón) */
    #container.ytd-searchbox {
        background-color: #FFFFFF !important;
        border: 1px solid #6D4C41 !important;
        border-radius: 8px !important;
    }
    
    #search-icon-legacy.ytd-searchbox {
        background-color: #FFF5CC !important;
        border: 1px solid #6D4C41 !important;
    }

    /* Barra lateral izquierda (Menú de navegación) */
    ytd-guide-renderer, ytd-mini-guide-renderer,
    #guide-content.ytd-guide-renderer {
        background-color: #FFF9E3 !important;
    }

    /* Botones principales y chips de categorías */
    yt-chip-cloud-chip-renderer {
        background-color: #FFF5CC !important;
        border: 1px solid #6D4C41 !important;
        color: #6D4C41 !important;
    }

    /* Miniaturas de videos (Bordes redondeados estilo tierno) */
    ytd-thumbnail img {
        border: 2px solid #6D4C41 !important;
        border-radius: 12px !important;
    }
}
